def find_closest_elements(numbers: List[float]) -> Tuple[float, float]:
    abs_diff = [(abs(numbers[i] - numbers[j]), numbers[i], numbers[j]) for i in range(len(numbers)) for j in range(i+1, len(numbers)]
    abs_diff.sort(key=lambda x: x[0])
    return min(abs_diff, key=lambda x: x[0])[1], min(abs_diff, key=lambda x: x[0])[2]

